-- Promotes ParkingEntranceForVehicles to a persisted @Entity (decision 0b), mirroring
-- StopPlace -> Quay. Generated by Hibernate schema export against the modified entity
-- during the 2026-09-03 spike (see plan_tiamat-parking-core-redo.md, commit 3), with
-- width/height corrected from the generated numeric(38,2) to numeric(10,2) to match the
-- @Column(precision = 10, scale = 2) added to SiteEntrance.

CREATE SEQUENCE parking_entrance_for_vehicles_seq
    START WITH 1
    INCREMENT BY 10
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE parking_entrance_for_vehicles (
    id                              bigint NOT NULL,
    netex_id                        varchar(255),
    version                         bigint NOT NULL,
    changed                         timestamp(6),
    created                         timestamp(6),
    from_date                       timestamp(6),
    to_date                         timestamp(6),
    changed_by                      varchar(255),
    version_comment                 varchar(255),
    name_value                      varchar(255),
    name_lang                       varchar(5),
    description_value               varchar(4000),
    description_lang                varchar(5),
    label_value                     varchar(255),
    label_lang                      varchar(5),
    private_code_type               varchar(255),
    private_code_value              varchar(255),
    public_code                     varchar(255),
    entrance_type                   varchar(255) CHECK (entrance_type IN (
                                        'OPENING','OPEN_DOOR','DOOR','SWING_DOOR','REVOLVING_DOOR',
                                        'AUTOMATIC_DOOR','TICKET_BARRIER','GATE','OTHER')),
    width                           numeric(10, 2),
    height                          numeric(10, 2),
    is_entry                        boolean,
    is_exit                         boolean,
    is_external                     boolean,
    dropped_kerb_outside            boolean,
    drop_off_point_close            boolean,
    all_areas_wheelchair_accessible boolean,
    covered                         smallint CHECK (covered BETWEEN 0 AND 4),
    level_ref                       varchar(255),
    level_ref_version               varchar(255),
    site_ref                        varchar(255),
    site_ref_version                varchar(255),
    centroid                        geometry,
    accessibility_assessment_id     bigint UNIQUE,
    multi_surface_id                bigint UNIQUE,
    place_equipments_id             bigint UNIQUE,
    polygon_id                      bigint UNIQUE,
    PRIMARY KEY (id),
    CONSTRAINT parking_entrance_for_vehicles_netex_id_version_constraint
        UNIQUE (netex_id, version)
);

CREATE TABLE parking_vehicle_entrances (
    parking_id           bigint NOT NULL,
    vehicle_entrances_id bigint NOT NULL UNIQUE
);

CREATE TABLE parking_entrance_for_vehicles_alternative_names (
    parking_entrance_for_vehicles_id bigint NOT NULL,
    alternative_names_id             bigint NOT NULL UNIQUE
);

CREATE TABLE parking_entrance_for_vehicles_check_constraints (
    parking_entrance_for_vehicles_id bigint NOT NULL,
    check_constraints_id             bigint NOT NULL UNIQUE
);

CREATE TABLE parking_entrance_for_vehicles_equipment_places (
    parking_entrance_for_vehicles_id bigint NOT NULL,
    equipment_places_id              bigint NOT NULL UNIQUE
);

CREATE TABLE parking_entrance_for_vehicles_facilities (
    parking_entrance_for_vehicles_id bigint NOT NULL,
    facilities_id                    bigint NOT NULL UNIQUE,
    PRIMARY KEY (facilities_id, parking_entrance_for_vehicles_id)
);

CREATE TABLE parking_entrance_for_vehicles_key_values (
    parking_entrance_for_vehicles_id bigint       NOT NULL,
    key_values_key                   varchar(255) NOT NULL,
    key_values_id                    bigint       NOT NULL UNIQUE,
    PRIMARY KEY (parking_entrance_for_vehicles_id, key_values_key)
);

CREATE TABLE parking_entrance_for_vehicles_local_services (
    parking_entrance_for_vehicles_id bigint NOT NULL,
    local_services_id                bigint NOT NULL UNIQUE
);

ALTER TABLE parking_entrance_for_vehicles
    ADD CONSTRAINT parking_entrance_accessibility_assessment_fk
        FOREIGN KEY (accessibility_assessment_id) REFERENCES accessibility_assessment,
    ADD CONSTRAINT parking_entrance_multi_surface_fk
        FOREIGN KEY (multi_surface_id) REFERENCES persistable_multi_polygon,
    ADD CONSTRAINT parking_entrance_polygon_fk
        FOREIGN KEY (polygon_id) REFERENCES persistable_polygon,
    ADD CONSTRAINT parking_entrance_place_equipments_fk
        FOREIGN KEY (place_equipments_id) REFERENCES installed_equipment_version_structure;

ALTER TABLE parking_vehicle_entrances
    ADD CONSTRAINT parking_vehicle_entrances_parking_fk
        FOREIGN KEY (parking_id) REFERENCES parking,
    ADD CONSTRAINT parking_vehicle_entrances_entrance_fk
        FOREIGN KEY (vehicle_entrances_id) REFERENCES parking_entrance_for_vehicles;

ALTER TABLE parking_entrance_for_vehicles_alternative_names
    ADD CONSTRAINT parking_entrance_alt_names_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_alt_names_target_fk
        FOREIGN KEY (alternative_names_id) REFERENCES alternative_name;

ALTER TABLE parking_entrance_for_vehicles_check_constraints
    ADD CONSTRAINT parking_entrance_check_constraints_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_check_constraints_target_fk
        FOREIGN KEY (check_constraints_id) REFERENCES check_constraint;

ALTER TABLE parking_entrance_for_vehicles_equipment_places
    ADD CONSTRAINT parking_entrance_equipment_places_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_equipment_places_target_fk
        FOREIGN KEY (equipment_places_id) REFERENCES equipment_place;

ALTER TABLE parking_entrance_for_vehicles_facilities
    ADD CONSTRAINT parking_entrance_facilities_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_facilities_target_fk
        FOREIGN KEY (facilities_id) REFERENCES site_facility_set;

ALTER TABLE parking_entrance_for_vehicles_key_values
    ADD CONSTRAINT parking_entrance_key_values_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_key_values_target_fk
        FOREIGN KEY (key_values_id) REFERENCES value;

ALTER TABLE parking_entrance_for_vehicles_local_services
    ADD CONSTRAINT parking_entrance_local_services_parent_fk
        FOREIGN KEY (parking_entrance_for_vehicles_id) REFERENCES parking_entrance_for_vehicles,
    ADD CONSTRAINT parking_entrance_local_services_target_fk
        FOREIGN KEY (local_services_id) REFERENCES local_service;

CREATE INDEX parking_vehicle_entrances_parking_id_index
    ON parking_vehicle_entrances (parking_id);
